def split_csv(line):
    fields = []
    i = 0
    n = len(line)
    if n == 0:
        return ['']
    while True:
        if i < n and line[i] == '"':
            i += 1
            field = []
            while True:
                if i >= n:
                    return None  # unterminated quoted field
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(c)
                    i += 1
            # after closing quote, must be followed by comma or end of line
            if i < n and line[i] != ',':
                return None
            fields.append(''.join(field))
            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break
        else:
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break
    return fields

